def _new_basketValue(trx,basketId):
    fascia_value=[0.0850,0.0723,0.0679,0.0638,0.0575,0.0563,0.0552,0.0541,0.0530]
    return trx * fascia_value[basketId]

def MycodiceArticolo(category,x):
    group_choices= {
        0:"A.1",
        1:"A.2",
        2:"A.3",
        3:"A.4",
        4:"A.5",
        5:"A.6",
        6:"A.7",
        7:"A.8",
        8:"A.9"
    }
    category_choices = {
        "A1":"B.3",
        "B1":"B.1",
        "B2":"B.2"
    }
    if ( category.startswith ("G") ) :
        result = group_choices.get(x,"A.9")
    else:
        result = category_choices.get(category)
    return result

